  'W4',
  $j${"md5": "57f2d790", "path": "ask588/w4/plan588.md", "commit": "23546e0b", "note": "rev 0 (3d33cd10, commit b33e3c75) with the rev 1 notes; D7 notes ask588/w4/plan588_D7.md 9595cd04 (commit 870fa882); read ask588/w4/read588.md 1e4b21a3", "source": "md5sum by W3 on all three files; Wall 11385, 11392, 11396"}$j$::jsonb,
