 "path": "ask588/w4/write/prewrite_eng588.json", "note": "fresh fetch before write 1; the same md5 as ask587/w4/write/fetchback_eng587.json (row 158)", "source": "md5sum by W3"}, {"md5": "9fcdb69e", "path": "ask588/w4/write/prewrite_child588.json", "note": "fresh fetch before write 1, child; the same md5 as ask587/w4/write/fetchback_child587.json", "source": "md5sum by W3"}, {"md5": "881ce914", "path": "ask588/w4/write/put_eng588.json", "note": "PUT body, engine, write 1", "source": "md5sum by W3"}, {"md5": "51fd19c5", "path": "ask588/w4/write/put_child588.json", "note": "PUT body, child", "source": "md5sum by W3"}, {"md5": "36b69a99", "path": "ask588/w4/write/fetchback_eng588.json", "note": "fetch-back after write 1; the same md5 as prewriteD7_eng588.json", "source": "md5sum by W3"}, {"md5": "d72f33f9", "path": "ask588/w4/write/fetchback_child588.json", "note": "fetch-back, child", "source": "md5sum by W3"}, {"md5": "3d2ce3c2", "path": "ask588/w4/write/putD7_eng588.json", "note": "PUT body, engine, write 2 (D7)", "source": "md5sum by W3"}, {"md5": "79e88f53", "path": "ask588/w4/write/fetchbackD7_eng588.json", "note": "fetch-back after write 2", "source": "md5sum by W3"}, {"md5": "9f3c44ac", "path": "ask588/w4/write/write588.sh", "note": "write script 1", "source": "md5sum by W3"}, {"md5": "eae79e9a", "path": "ask588/w4/write/write588D7.sh", "note": "write script 2", "source": "md5sum by W3"}]$j$::jsonb,
